-- Importação histórica TSE: ELEITOS (prefeito/vereador, incl. média) de 2000, 2004 e 2008 no PA.
-- Votos = max(QT_VOTOS_NOMINAIS, QT_VOTOS_NOMINAIS_VALIDOS) somados por zona.
-- Limpeza defensiva (idempotência):
DELETE FROM "Resultado" WHERE id LIKE 'hist2000-%' OR id LIKE 'hist2004-%' OR id LIKE 'hist2008-%';
DELETE FROM "Candidato" WHERE id LIKE 'hist2000-%' OR id LIKE 'hist2004-%' OR id LIKE 'hist2008-%';
DELETE FROM "Cargo" WHERE id LIKE 'hist2000-%' OR id LIKE 'hist2004-%' OR id LIKE 'hist2008-%';
DELETE FROM "Eleicao" WHERE id IN ('hist2000','hist2004','hist2008');
